const ALLOWED_CHANNELS=['<YOUR_SLACK_CHANNEL_ID>'];
function soql(value){return String(value).replace(/\\/g,'\\\\').replace(/'/g,"\\'");}

function parseMention(event){
 if(event.type!=='app_mention'||event.bot_id||event.bot_profile||event.subtype==='bot_message')return null;
 const user=String(event.user||''),channel=String(event.channel||''),ts=String(event.ts||event.event_ts||'');
 if(!/^[UW][A-Z0-9]+$/.test(user)||! /^[CG][A-Z0-9]+$/.test(channel)||! /^\d{10,}\.\d{6}$/.test(ts))throw new Error('Invalid mention routing fields');
 const input=String(event.text||'').replace(/^\s*<@[UW][A-Z0-9]+(?:\|[^>]+)?>\s*/,'').trim();
 const match=input.match(/^prep(?:\s+([\s\S]*))?$/i);
 if(!match)return null;
 const route={request_id:'slack:'+channel+':'+ts,user_id:user,channel_id:channel,message_ts:ts};
 if(!ALLOWED_CHANNELS.includes(channel))return {...route,route:'hint',hint:'This app is not enabled in this channel. Please use an approved meeting-prep channel.'};
 let text=String(match[1]||'').trim();
 if(!text||text.length>300)return {...route,route:'hint',hint:text.length>300?'Please keep the name or email lookup under 301 characters.':'Usage: mention this app, then type prep followed by a name or email. Example: @app prep Mira Zantello'};
 text=text.replace(/<mailto:([^>|]+)(?:\|[^>]+)?>/gi,'$1');
 const email=text.match(/[A-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i)?.[0]?.toLowerCase();
 return {request_id:'slack:'+channel+':'+ts,user_id:user,channel_id:channel,message_ts:ts,route:'lookup',lookup_type:email?'email':'name',lookup_value:email||text,lookup_soql:soql(email||text),empty:!text};
}

const request=parseMention($input.first().json);
